import sys

def reorganize(n, layers):
    directions = []
    for i in range(n):
        directions.append((i+1) % n)
        directions.append((n+1-i) % n)
        directions.append((n+i) % n)
    output = [0]*n
    for layer in layers:
        for x in layer:
            if x == '0':
                for i in directions:
                    if output[i-1] == 0:
                        output[i-1] = 1
                        break
    for i in range(n):
        output[i] = (output[i] <= n - 2) + (output[n-1-i] <= n - 2)
    return [str(x+1) for x in output[:-1]], [str(x+1) for x in output[1:]], [str(x+1) for x in output[2:]]

