import heapq

def solve(m, a, b, edges):
    graph = [[] for _ in range(m)]
    for u, v, c in edges:
        graph[u-1].append((v-1, c))
        graph[v-1].append((u-1, c))

    def floyd_warshall(d, mp):
        for k in range(m):
            for i in range(m):
                for j in range(m):
                    if d[i][j] > d[i][k] + d[k][j]:
                        d[i][j] = d[i][k] + d[k][j]
                        if k in mp and i in mp and j in mp:
                            mp["distances"] = d
                        mp["parents"] = [k for k in range(m)]

    d = [[float('inf')] * m for _ in range(m)]
    mp = {"distances": d, "parents": defaultdict(int)}
    floyd_warshall(d, mp)

    distToEndings = [float('inf')] * m
    apex = 2 * a
    distToEndings[0] = 0
    seen = set()
    candidates = [(0, 0)]
    while candidates:
        prev_cost, k = heapq.heappop(candidates)
        if k == m - 1:
            break
        for neighbor, c in graph[k]:
            if neighbor in seen or c not in (a, b):
                continue
            new_cost = prev_cost + c
            new_distToEnd = min(new_cost, distToEndings[neighbor])
            if new_distToEnd < distToEndings[neighbor]:
                distToEndings[neighbor] = new_distToEnd
                heapq.heappush(candidates, (new_cost, neighbor))
        seen.add(k)

    dp = [float('inf')] * m
    dp[0] = 0
    mp = {"distances": dp}
    dp.sort()
    distToEndings.sort()

    ans = [float('inf')] * n
    for u, c in edges:
        roadPossible = distToEndings[0] == 0 and c in (a, b)
        par, ret = None, float('inf')
        mth = 0
        while mth < m:
            d = distToEndings[mth]
            k = mp["distances"].index(d[0])
            if mth >= d[1]:
                if c == a:
                    if roadPossible:
                        ret = c
                    else:
                        break
                elif c == b:
                    if roadPossible:
                        ret = b
            if ret == float('inf') and roadPossible and u not in seen:
                break
            seen.add(u)
            mth += 1
            if k in seen and ret == float('inf'):
                dp[k] = ret
                seen.remove(k)
                break
            if ret > 0:
                dp[k] = min(ret - c, dp[k])
                if c == a:
                    dp[k] = min(dp[k], 0)
                    break

        ans[mp["parents"][mp["distances"].index(ret))] = min(ans[mp["parents"][mp["distances"].index(ret)]], dp[k])

    return ans

