from collections import deque

def checkered_distance(n, m, x, y, direction):
    robot = [x, y-1, direction]
    path = deque([[x, y]])
    if direction == "UL":
        robot[1] += 2
    elif direction == "UR":
        robot[1] += 2
    changes = {"UL": 1, "UR": 0, "DL": 3, "DR": 2}
    wall_check = {"UL": {1, 2}, "UR": {1}, "DL": {3}, "DR": {1, 2}}

    while robot[0] < m:
        for _ in range(3):
            x, y = robot
            y += changes[direction]
            robot = x, y, direction

            if (x, y) == path[0]:
                path.append(robot)
                if len(path) > 1:
                    dx = x - path[0][0]
                    dy = y - path[0][1]
                    path.appendleft([path[-1][0], path[-1][1]])
                    if dx not in wall_check[direction] and dy not in wall_check[direction]:
                        return len(path)
                path.popleft()
                break
            else:
                path.append(robot)

    return -1

