import sys
from bisect import bisect_right

def init_tree(array):
    tree = []
    for i, a in enumerate(array):
        tree.append([-1, 0])
        tree.append(a)
        if i > 0:
            m = len(tree) - 2
            while True:
                mid = m // 2
                if tree[mid][0] >= 0:
                    m -= mid
                else:
                    m = mid - mid // 2 - 1
            tree[-2][0] -= tree[-2][1]
            tree[-2][0] = -tree[-2][0]
    return tree

def search_transformation(tree, arr, transform, m, leaf=True):
    size = len(tree)
    offset = bisect_right(tree, [0, 0])
    last = None
    if leaf:
        value = tree[-size // 2 - offset + len(tree) - 1]
        return value[1]
    else:
        elements = arr[0]
        for i, v in enumerate(arr):
            if m & (1 << i):
                value = tree[offset - i][1]
                if m & (1 << len(tree) - 1) or last == value:
                    last = value
                    return value
                else:
                    last = v
                    continue
            else:
                elements |= v << i
        return elements | last << m.bit_length() | last

def process_fourth_case():
