from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if xroot == yroot:
        return
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def is_cyclic(i1, i2, edges, limit):

    for i in range(len(edges)):
        x1, y1, c1 = edges[i]
        if x1 == i1:
            continue
        x2, y2, c2 = edges[i]
        if y1 == i2 and y2 == i1 and c1 != c2:
            return True

    s = [[i, j, c1] for i,j,c1 in edges if i1 == i]
    s += [[i1, i2, c2]]
    s += [[i2, j, c2] for i,j,c2 in edges if i2 == j]

    def DFS(s, visited, time):
        visited[i] = True
        if i2 in s:
            DFS(s, visited, c1)
        for j,c in visited:
            res.append(abs(c/limit - time))
        return res

    for e in s:
        i, j, c = e[0], e[1], e[2]
        res = []
        flag = False
        for i,j,c in s:
            if i != i1 and i != j and j != i and j != i1 and c != c1 and is_cyclic(i, j, s, c):
                flag = True

        if not flag:
            visited = [False]*(len(s)+1)
            fr = 0
            for _i,j,c in s:
                if i1 == _i:
                    visited[i] = True
                DFS(s, visited, c)
                fr += res[-1]-res[0]
            return fr/len(res)
    return False

if __name__ == "__main__":
