from heapq import heappush, heappop
from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rank[rootX] < rank[rootY]:
        parent[rootX] = rootY
    elif rank[rootX] > rank[rootY]:
        parent[rootY] = rootX
    else:
        parent[rootY] = rootX
        rank[rootX] += 1

def kruskal(parent, rank, edge):
    mst = 0
    for u, v, c in edge:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst += c
    return mst

def pathfinding(parent, dist, source, dest):
    visited = set()
    visited.add(source)
    mst = 0
    visited[source] = 0
    while len(visited) < len(parent):
        min_cost = float('inf')
        for i in range(len(parent)):
            if i not in visited and parent[i] == i:
                if dist[i] < parent[parent[i]]:
                    parent[i] = parent[parent[i]]
                    dist[i] = dist[parent[i]]
                    mst += dist[i]
                    visited[i] = 0
                    edge = parent, parent[parent[i]], dist[i]
                    mincosts.add(edge)
                elif (dist[i] < dist[parent[i]]) and (dist[i] < min_cost):
                    min_cost = dist[i]
                    min_edge = parent, parent[parent[i]], dist[i]
                    dist[i] = dist[parent[i]]
                    parent[i] = i
                    visited[i] = 0
                    edge = parent, parent[parent[i]], dist[i]
                    mincosts.add(edge)
    if dest not in visited:
        return float('inf')
    return mst + mincosts[visited.index(dest)]

