from collections import defaultdict

def min_operations_to_reach_all_v(vertices, edge, a):
    """
    Function to calculate the minimum number of operations required to remove all vertices from a tree.
    """
    # Initialize graph
    g = defaultdict(list)
    for u, v in edge:
        g[u].append(v)
        g[v].append(u)

    # Mark white vertices
    vertices_to_remove = [i for i, x in enumerate(a) if x == 1]

    # Function to perform dfs and find the shortest path to a white vertex
    shortest_paths = {}
    def dfs(vertex, parent, distance):
        if vertex in shortest_paths:
            return False
        shortest_paths[vertex] = (distance, parent)
        for next_vertex in g[vertex]:
            if next_vertex != parent and not dfs(next_vertex, vertex, distance + 1):
                return False
        return True

    white_path_found = False
    for vertex in vertices_to_remove[1:]:
        if white_path_found:
            continue
        for u in shortest_paths[vertex]:
            if a[u] == 1:
                white_path_found = True
                break
        else:
            continue
        break

    # If no white path is found, make a choice by visiting white and black vertices
    if not white_path_found:
        return len(vertices_to_remove)

    # Create a mapping of white vertices
    white_to_root = {}
    tmp_vertices = {}

    # Traverse the tree using depths-first search
    stack, buffer = [], [0]
    while buffer:
        v = buffer.pop()
        vertex, d, parent = shortest_paths[v][0], shortest_paths[v][1], -1
        if not white_path_found:
            if a[vertex] == 2:
                white_to_root[vertex] = 1
            if a[vertex] not in (0, 1):
                stack.append((vertex, d, parent, 2))
                continue
        buffer.append(vertex)
        while stack:
            last_v = stack.pop()
            vertex, d, parent, letter = last_v[0], last_v[1], last_v[2], last_v[3]
            if a[vertex] == 1:
                if not white_path_found:
                    white_to_root[vertex] = 1
                    continue
                for edge in g[vertex]:
                    if a[edge] in (2, 0):
                        white_to_root[vertex] = 2
                        break
            else:
                stack.append((edge, d + 1, vertex, letter))
        buffer.append(vertex)
        tmp_vertices[vertex] = buffer[-1]

    white_to_depth = {v: d for v, d in sorted(tmp_vertices.items(), key=lambda x: abs(x[1] - x[0]))}
    depth_to_WHITE = lambda d1, d2: d1 < abs(d1 - d2) > d2
    has_banned路人 = {}

    def solution(vertex, incoming):
        if incoming in has_banned路人:
            return min_operations_to_reach_all_v([white_to_root[v] for v in incoming], edge, [min_operations_to_reach_all_v([white_to_root[v] for v in incoming], edge, [min_operations_to_reach_all_v([v for v in incoming if v != i], edge, [a[v]]) for i in connected_vertices]) for incoming in connected_vertices] for connected_vertices in g[vertex] for d in depth_to_WHITE(vertex, d))
        return [d, white_to_root[vertex], connected_vertices] for vertex, d in white_to_depth.items()]

    return min(solution(vertex, incoming) for vertex, incoming in solution(left, incoming) for (a[left], left), incoming in solution(left, incoming) for left in incoming if left not in has_banned路人)
