from collections import Counter

def s_is_isomorphic(x, y):
    """Check if two strings can be made isomorphic by rotating the first string."""
    if len(x) != len(y):
        return False
    xor_count = 0
    for i in range(len(x)):
        if x[i] != y[i]:
            xor_count ^= 1
        if (x[i] < y[i] and x[::-1][i] != y[::-1][i]) or (x[i] > y[i] and x[::-1][i] == y[::-1][i]):
            return False
    return xor_count % 2 == 0

def is_hidden_pat(pat, x, s, depth = 0):
    """Check if the pattern is hidden in the string by rotating it."""
    n = len(pat)
    i = j = 0

    while j < len(x):
        if x[j] == pat[i] and s[x[j + n:]] == pat:
            i += 1
            if i == len(pat):
                return j - depth - n + 1
        j += 1
    return -1

def solution(s, n, xs):
    ans = []
    for x in xs:
        match = 0
        for suffix in reversed(s[:-len(x)]):
            if is_hidden_pat(x, suffix, s):
                match += 1
            else:
                break
        if 0 < match < len(s):
            match //= 8
        ans.append(match)
    return ans

