                while j >= index[1]:
                    i = j - index[1]
                    need, prev = indices[j][0], indices[i][0]
                    need = indices[j][0] - need
                    if need > need:
                        if prev - need > need:
                            need -= prev
                            indices[i][0] -= need
                        elif (prev - need) < need:
                            indices[i][0] -= prev
                        j = i - 1
                        need -= prev
                        break
                    if prev - need == need:
                        indices[j][0] -= prev
                        indices[i][0] -= prev
