        return "Possible" if any(s < 0 for s in inflows) else "Impossible"

    g = defaultdict(list)
    for z, y in pipes:
        g[z-1].append(z)
        g[y-1].append(y)

    def floyed_warshall(g):
        for xi in range(len(g)):
            for yi in range(len(g)):
                g[yi] = [z for z in g[yi] if z != xi]
            for yi in range(len(g)):
                for yj in g[yi]:
                    g[yj].extend(g[yj].pop(yi))
            for zi in range(len(g)):
                for yi in range(len(g)):
                    if yi == zi: continue
                    g[zi] = sorted(g[zi] + g[yi], key=lambda c: c[0])

    floyed_warshall(g)

    flow_sources = [i for i in range(len(g)) if all(a < 0 for a in g[i])]
    flow_sinks = [i for i in range(len(g)) if all(a > 0 for a in g[i])]

    # 6 edges
    def articulation(p, depth):
        if p == -1: return [True]
        if depth[p] != 0: return [True]
        cc_depths = {}
        for dp, a in articulation(g[p], depth + 1):
