        self.bias = 0
        for j, l in enumerate(t):
            while i > 1 and s[self.suffix_array[index]] == s[self.suffix_array[index - 2]]:
                index -= 2
            if j - i > self.bias:
                self.bias = j - i
            self.finish_array[self.suffix_array[index]] = s.index(l)
            if j - i >= self.bias:
                index += 1
                i = self.finish_array[self.suffix_array[index]] - self.finish_array[self.suffix_array[index - 1]]
                if index == 0:
                    self.suffix_array[index] = i

