def find_f(size, flow):
    s = []
    for i in range(size):
        s.append((i, 0))
    for i in range(size):
        s.append((i + size, flow[i]))

    f = [0] * (2 * size)

    while 0 in [ t[1] for t in s ]:
        for i in range(size):
            if s[i][1] > 0:
                for j in range(i * 2 + 1, size * 2, 2):
                    if s[j][0] < i:
                        f[j] *= -1
                        s[j] = (s[j][0], s[j][1] + flow[s[i][0]])

    return sum(flow), f[size + size:]
